(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*6+Math.cos(y*0.035+t*0.4)*5;
  const w2y = Math.cos(y*0.038+t*0.45)*6+Math.sin(x*0.032-t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.3],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, -0.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, -0.4],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, -0.3],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 0.4],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.13, 1.8, -0.1],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*60, 0.075, 2.4, 0.2],
    [300+Math.cos(t*0.7+4)*80, 100+Math.sin(t*0.5+5)*90, 0.095, 1.6, -0.5]
  ];
  let aS=0, iS=0, fS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp+ph);
    const d2=Math.sqrt((sx-sX+20)**2+(sy-sY+15)**2);
    aS+=wave;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    fS+=Math.sin((d+d2)*f*0.3-t*sp*0.4)*0.5;
  }
  const act=aS/10, inh=iS/10, feed=fS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08+ang*2+t*0.8))*0.27;
  const micro=(Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)+Math.sin((sx-sy)*0.25+t*2))*0.15;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((feed+inh*0.5-act*0.3+spiral*-0.5+micro)*1.8);
  const coupling=Math.tanh((rd1+rd2)*1.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{let md=99;for(let i=0;i<src.length;i++){const dx=sx-src[i][0],dy=sy-src[i][1];md=Math.min(md,Math.sqrt(dx*dx+dy*dy));}return md;};
  const vEdge=1-Math.min(1,Math.max(0,(voronoi()-12)*0.15));
  const blend=coupling*0.6+cell*0.2+rd1*rd2*0.2;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,82],[18,88,108],[28,138,128],[75,168,118],[165,185,80],[210,175,65],[215,130,62],[195,82,62],[148,48,58],[85,28,58],[40,18,55],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(coupling*Math.PI)*0.2+Math.abs(rd1*rd2)*0.1;
  const edge=(Math.abs(coupling)>0.65?1.12:1.0)*(1+vEdge*0.08);
  const glow=Math.max(0,1-Math.abs(coupling))*0.15;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*55)|0
  ];
}
